#!/bin/bash
set -euo pipefail
[[ $EUID == 0 ]] || exit 1
cd /opt/jarlhalla-ai
backup=$(mktemp -d /root/jarlhalla-console-backup-XXXXXXXX)
cp -a app.py "$backup/app.py"
for f in jarlhalla_console.py jarlhalla_console.html; do
  if [[ -e $f ]]; then cp -a "$f" "$backup/$f"; fi
done
rollback() {
  cp -a "$backup/app.py" app.py
  for f in jarlhalla_console.py jarlhalla_console.html; do
    if [[ -f $backup/$f ]]; then cp -a "$backup/$f" "$f"; else rm -f "$f"; fi
  done
  systemctl restart jarlhalla-ai.service
  echo "Installation rolled back: $backup"
}
trap rollback ERR
base64 -d > jarlhalla_console.py <<'DATA'

DATA
base64 -d > jarlhalla_console.html <<'DATA'

DATA
venv/bin/python - <<'PYCODE'
from pathlib import Path
p=Path('app.py')
s=p.read_text()
marker='from jarlhalla_console import router as console_router'
if marker not in s:
    p.write_text(s+'
'+marker+'
app.include_router(console_router)
')
PYCODE
chown jarlhalla-ai:jarlhalla-ai app.py jarlhalla_console.py jarlhalla_console.html
chmod 644 jarlhalla_console.py jarlhalla_console.html
venv/bin/python -m py_compile app.py jarlhalla_console.py
venv/bin/python -c 'import app; assert any(r.path == "/workspace" for r in app.app.routes)'
systemctl restart jarlhalla-ai.service
ready=0
for attempt in {1..20}; do
 if curl -fsS --max-time 2 http://127.0.0.1:8787/workspace > /dev/null 2>&1; then ready=1; break; fi
 sleep 1
done
[[ $ready == 1 ]]
trap - ERR
echo "PASS: http://127.0.0.1:18787/workspace"
echo "Backup: $backup"
